const ids={home:'9:6',explore:'9:8',cart:'9:10',account:'9:13'};
const log=[];
for(const [k,id] of Object.entries(ids)){
  const f=await figma.getNodeByIdAsync(id);
  const tab=f.children.find(c=>c.type==='INSTANCE'&&/^Tab Bar/.test(c.name));
  if(!tab){log.push(k+': no tab bar');continue;}
  f.children.filter(c=>c.name&&c.name.startsWith('Tab Hit')).forEach(c=>c.remove());
  const targets=[['Shop',ids.home],['Explore',ids.explore],['Cart',ids.cart],['Favourite',null],['Account',ids.account]];
  targets.forEach(([label,dest],i)=>{
    const hit=figma.createRectangle();
    hit.name='Tab Hit '+label;
    hit.resize(82.8,92);
    hit.fills=[];
    f.appendChild(hit);hit.x=i*82.8;hit.y=tab.y;
    if(dest&&dest!==id){
      try{
        hit.reactions=[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:dest,navigation:'NAVIGATE',transition:{type:'SMART_ANIMATE',easing:{type:'EASE_OUT'},duration:0.3},preserveScrollPosition:false}]}];
        log.push(k+'/'+label+' → ok');
      }catch(e){log.push(k+'/'+label+' FAIL '+e.message.slice(0,60));}
    }
  });
}
return JSON.stringify(log);

