// keep the click reaction, add a time-based auto advance
const reactions=(splash.reactions||[]).filter(r=>r.trigger.type!=='AFTER_TIMEOUT');
const reactions2=reactions.map(r=>{
  // strip the timeout flag so click fires immediately
  const t={...r.trigger};delete t.timeout;
  return {...r,trigger:t};
});
try{
  splash.reactions=[...reactions2,{trigger:{type:'AFTER_TIMEOUT',timeout:2200},actions:[{type:'NODE',destinationId:onb.id,navigation:'NAVIGATE',transition:{type:'DISSOLVE',easing:{type:'EASE_IN_AND_OUT'},duration:0.4},preserveScrollPosition:false}]}];
}catch(e){
  return JSON.stringify({error:e.message,before});
}
return JSON.stringify({before,after:(splash.reactions||[]).map(r=>r.trigger.type+'→'+(r.actions[0]&&r.actions[0].destinationId))});

